from __future__ import annotations

import json
from datetime import datetime
from pathlib import Path
from typing import Any


TASK_ID = "CSX-106_Q1"
EVENT_ID = "CSX-106"
TASK_DIR = Path(__file__).resolve().parent
WORKSPACE_ROOT = Path(__file__).resolve().parents[3]
EVENT_DIR = WORKSPACE_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUT_PATH = TASK_DIR / "computed_gt.json"

HOURLY_WEATHER = "data/physical_hazard/physical_hazard_002_Open-Meteo_historical_wind_rain_point_API.json"
EVENT_META = "metadata/event.json"


def read_json(relative_path: str) -> Any:
    return json.loads((EVENT_DIR / relative_path).read_text(encoding="utf-8-sig"))


def round_float(value: float, digits: int = 1) -> float:
    return round(float(value), digits)


def extremum_indices(values: list[float], *, find_max: bool) -> list[int]:
    target = max(values) if find_max else min(values)
    return [index for index, value in enumerate(values) if value == target]


def hour_delta(later: datetime, earlier: datetime) -> int:
    return int((later - earlier).total_seconds() // 3600)


def main() -> None:
    event = read_json(EVENT_META)
    hourly = read_json(HOURLY_WEATHER)["hourly"]

    times_text = hourly["time"]
    times = [datetime.fromisoformat(value) for value in times_text]
    wind = [float(value) for value in hourly["wind_speed_10m"]]
    gust = [float(value) for value in hourly["wind_gusts_10m"]]
    pressure = [float(value) for value in hourly["pressure_msl"]]
    rain = [float(value) for value in hourly["precipitation"]]

    gust_index = extremum_indices(gust, find_max=True)[0]
    wind_index = extremum_indices(wind, find_max=True)[0]
    pressure_index = extremum_indices(pressure, find_max=False)[0]
    rain_indices = extremum_indices(rain, find_max=True)

    gust_time = times[gust_index]
    rain_lags = [hour_delta(gust_time, times[index]) for index in rain_indices]
    near_peak_rain = sum(
        value
        for time, value in zip(times, rain)
        if abs(hour_delta(time, gust_time)) <= 3
    )

    peak_values = {
        "peak_gust_kmh": round_float(gust[gust_index]),
        "peak_wind_speed_kmh": round_float(wind[wind_index]),
        "minimum_pressure_hpa": round_float(pressure[pressure_index]),
        "point_rainfall_total_mm": round_float(sum(rain)),
        "hourly_rainfall_peak_mm": round_float(rain[rain_indices[0]]),
    }
    peak_times = {
        "gust": times_text[gust_index],
        "wind": times_text[wind_index],
        "pressure": times_text[pressure_index],
        "rain_peak_times": [times_text[index] for index in rain_indices],
    }
    timing_tests = {
        "wind_gust_same_hour": wind_index == gust_index,
        "pressure_lag_hours_after_gust": hour_delta(times[pressure_index], gust_time),
        "nearest_rain_peak_lag_hours_before_gust": min(rain_lags),
        "earliest_rain_peak_lag_hours_before_gust": max(rain_lags),
        "rain_mm_within_3h_of_gust": round_float(near_peak_rain),
    }

    primary_gt = {
        "target_family": "temporal_peak_consistency_ledger",
        "answer": "late_wind_pressure_pulse_with_offset_rain_peaks",
        "peak_values": peak_values,
        "peak_times": peak_times,
        "timing_tests": timing_tests,
        "computed_interpretation": (
            "Wind and pressure extrema form a late-window pulse; hourly rainfall peaks are offset from that pulse."
        ),
    }

    rubric = {
        "total_points": 20,
        "criteria": [
            {
                "name": "Final ledger and label",
                "points": 3,
                "description": (
                    "Returns the requested compact JSON and labels the result "
                    "late_wind_pressure_pulse_with_offset_rain_peaks."
                ),
                "partial_credit": (
                    "Award 1-2 points for an equivalent label with incomplete JSON; no credit for a broad "
                    "narrative without the ledger."
                ),
            },
            {
                "name": "Peak values and units",
                "points": 4,
                "description": (
                    "Reports 111.6 km/h gust, 61.4 km/h 10 m wind, 989.6 hPa minimum pressure, "
                    "13.1 mm total point rainfall, and 0.9 mm hourly rainfall peak."
                ),
                "partial_credit": (
                    "Award roughly 0.8 points per correct value; cap at 3 points if units or rounding are unclear."
                ),
            },
            {
                "name": "Peak times and rainfall tie handling",
                "points": 4,
                "description": (
                    "Reports gust and wind at 2017-10-16T14:00, pressure at 2017-10-16T15:00, "
                    "and both rainfall-peak times."
                ),
                "partial_credit": (
                    "Award 2-3 points for correct wind-pressure times but only one rainfall-peak time; "
                    "award 1 point for a partly correct time list."
                ),
            },
            {
                "name": "Timing arithmetic",
                "points": 4,
                "description": (
                    "Computes same-hour wind/gust as true, pressure lag as 1 hour, nearest rainfall-peak lag "
                    "as 22 hours before gust, earliest rainfall-peak lag as 127 hours before gust, and 0.4 mm "
                    "within the 3-hour gust window."
                ),
                "partial_credit": (
                    "Award credit for each correct timing test; reduce credit for wrong sign conventions."
                ),
            },
            {
                "name": "Event-window source discipline",
                "points": 2,
                "description": (
                    "Derives the peak ledger from the event-window hourly point-weather arrays and does not "
                    "score or substitute separate daily cross-check values."
                ),
                "partial_credit": (
                    "Award 1 point if the hourly extrema are mostly correct but the proof mixes in unrequested "
                    "daily summaries."
                ),
            },
            {
                "name": "Concise computed interpretation",
                "points": 3,
                "description": (
                    "States that the wind-pressure extrema form a late-window pulse and rainfall peaks are "
                    "offset, without adding loss totals, public guidance, or broad event narration."
                ),
                "partial_credit": (
                    "Award 1-2 points for the right conclusion with extra unneeded prose."
                ),
            },
        ],
    }

    computed_gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": "temporal_peak_consistency_ledger",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "hour_count": len(times),
            "tolerances": {
                "numeric_values": 0.2,
                "hour_offsets": 0,
            },
        },
        "rubric": rubric,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                EVENT_META,
                HOURLY_WEATHER,
            ],
        },
    }

    OUT_PATH.write_text(json.dumps(computed_gt, ensure_ascii=True, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
